local BarometerMaker = {}
local PRODUCTS = {
    brass_barometer = { name = "Medeninast barometer", brassCost = 2, glassCost = 1, mercuryCost = 1, time = 5, cost = 80, accuracy = 50, prestige = 4, description = "Medeninast barometer za napovedovanje vremena." },
    silver_barometer = { name = "Srebrn barometer", silverCost = 2, glassCost = 1, mercuryCost = 1, time = 7, cost = 200, accuracy = 65, prestige = 8, happiness = 1, description = "Srebrn barometer za učenjake." },
    engraved_barometer = { name = "Vgraviran barometer", silverCost = 2, goldCost = 1, glassCost = 1, mercuryCost = 1, time = 10, cost = 460, accuracy = 78, prestige = 14, happiness = 2, description = "Vgraviran barometer z vremenskimi oznakami." },
    silver_dial_barometer = { name = "Srebrnokazalni barometer", silverCost = 2, goldCost = 1, glassCost = 1, mercuryCost = 1, brassCost = 1, time = 13, cost = 950, accuracy = 88, prestige = 22, happiness = 4, description = "Barometer s srebrnim kazalcem za plemiče." },
    gold_cased_barometer = { name = "Zlatokondični barometer", goldCost = 2, silverCost = 1, glassCost = 1, mercuryCost = 1, jewelCost = 1, time = 16, cost = 1900, accuracy = 94, prestige = 34, happiness = 6, description = "Barometer z zlatim ohišjem za visoke plemiče." },
    royal_grand_barometer = { name = "Kraljevski veliki barometer", goldCost = 3, silverCost = 2, jewelCost = 2, pearlCost = 1, glassCost = 1, mercuryCost = 1, time = 22, cost = 3800, accuracy = 100, prestige = 60, happiness = 12, description = "Veliki kraljevski barometer z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Barometerska delavnica", cost = { gold = 350, wood = 140, stone = 250 }, upkeep = 9, qualityBonus = 5 },
    glass_tube_room = { name = "Steklenocevna soba", cost = { gold = 1200, wood = 280, stone = 500, glass = 8 }, upkeep = 30, qualityBonus = 18 },
    mercury_room = { name = "Živosrebrna soba", cost = { gold = 2800, wood = 400, stone = 800, silver = 40, mercury = 8 }, upkeep = 70, qualityBonus = 30 },
    royal_barometer_atelier = { name = "Kraljevski atelje barometrov", cost = { gold = 12000, wood = 600, stone = 1200, gold = 80, jewel = 25 }, upkeep = 240, qualityBonus = 55, prestigeBonus = 50 },
}
BarometerMaker.brassStock = 14; BarometerMaker.glassStock = 10; BarometerMaker.mercuryStock = 12; BarometerMaker.silverStock = 8; BarometerMaker.goldStock = 6; BarometerMaker.jewelStock = 6; BarometerMaker.pearlStock = 4
BarometerMaker.productStock = {}; BarometerMaker.buildings = {}; BarometerMaker.maker = nil; BarometerMaker.activeMaking = {}; BarometerMaker.totalProducts = 0; BarometerMaker.dayTimer = 0
function BarometerMaker.init() BarometerMaker.brassStock=14; BarometerMaker.glassStock=10; BarometerMaker.mercuryStock=12; BarometerMaker.silverStock=8; BarometerMaker.goldStock=6; BarometerMaker.jewelStock=6; BarometerMaker.pearlStock=4; BarometerMaker.productStock={}; BarometerMaker.buildings={}; BarometerMaker.maker=nil; BarometerMaker.activeMaking={}; BarometerMaker.totalProducts=0; BarometerMaker.dayTimer=0; print("[BarometerMaker] Royal Barometer Maker System initialized (6 products, 4 buildings)") end
function BarometerMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; BarometerMaker.maker={name=n or ("Barometrar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Barometrar najet: %s (spretnost: %d)",BarometerMaker.maker.name,s),"success") end; return true end
function BarometerMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function BarometerMaker.build(id) local ok,e=BarometerMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(BarometerMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function BarometerMaker.getQualityBonus() local b=0; for _,bd in ipairs(BarometerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function BarometerMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.brassCost and BarometerMaker.brassStock<(d.brassCost or 0) then return false,"Premalo medenine" end; if d.glassCost and BarometerMaker.glassStock<(d.glassCost or 0) then return false,"Premalo stekla" end; if d.mercuryCost and BarometerMaker.mercuryStock<(d.mercuryCost or 0) then return false,"Premalo živega srebra" end; if d.silverCost and BarometerMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and BarometerMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and BarometerMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and BarometerMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #BarometerMaker.buildings==0 then return false,"Potrebna delavnica" end; if not BarometerMaker.maker then return false,"Potreben barometrar" end; return true end
function BarometerMaker.make(pt,qty) qty=qty or 1; local ok,e=BarometerMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.brassCost then BarometerMaker.brassStock=BarometerMaker.brassStock-d.brassCost*qty end; if d.glassCost then BarometerMaker.glassStock=BarometerMaker.glassStock-d.glassCost*qty end; if d.mercuryCost then BarometerMaker.mercuryStock=BarometerMaker.mercuryStock-d.mercuryCost*qty end; if d.silverCost then BarometerMaker.silverStock=BarometerMaker.silverStock-d.silverCost*qty end; if d.goldCost then BarometerMaker.goldStock=BarometerMaker.goldStock-d.goldCost*qty end; if d.jewelCost then BarometerMaker.jewelStock=BarometerMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then BarometerMaker.pearlStock=BarometerMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if BarometerMaker.maker then t=math.max(1,t-math.floor(BarometerMaker.maker.skill/12)) end; table.insert(BarometerMaker.activeMaking,{id="barometer_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,accuracy=d.accuracy or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function BarometerMaker.completeMaking(m) local q=1.0+(BarometerMaker.getQualityBonus()/100); if BarometerMaker.maker then q=q+(BarometerMaker.maker.skill/150) end; q=math.min(2.5,q); BarometerMaker.productStock[m.productType]=(BarometerMaker.productStock[m.productType] or 0)+m.quantity; BarometerMaker.totalProducts=BarometerMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if BarometerMaker.maker then BarometerMaker.maker.itemsMade=BarometerMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then BarometerMaker.maker.skill=math.min(100,BarometerMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Barometer izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"barometer.completed",{productName=m.productName,accuracy=m.accuracy,prestige=m.prestige,happiness=m.happiness}) end end
function BarometerMaker.update(dt) if not _G.state then return end; BarometerMaker.dayTimer=BarometerMaker.dayTimer+dt; if BarometerMaker.dayTimer>=30 then BarometerMaker.dayTimer=0; for i=#BarometerMaker.activeMaking,1,-1 do local m=BarometerMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then BarometerMaker.completeMaking(m); table.remove(BarometerMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(BarometerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if BarometerMaker.maker then tu=tu+18 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function BarometerMaker.getStats() return {brassStock=BarometerMaker.brassStock,glassStock=BarometerMaker.glassStock,mercuryStock=BarometerMaker.mercuryStock,silverStock=BarometerMaker.silverStock,goldStock=BarometerMaker.goldStock,jewelStock=BarometerMaker.jewelStock,pearlStock=BarometerMaker.pearlStock,productStock=BarometerMaker.productStock,numBuildings=#BarometerMaker.buildings,hasMaker=BarometerMaker.maker~=nil,makerName=BarometerMaker.maker and BarometerMaker.maker.name or "—",makerSkill=BarometerMaker.maker and BarometerMaker.maker.skill or 0,activeMaking=#BarometerMaker.activeMaking,totalProducts=BarometerMaker.totalProducts} end
return BarometerMaker
